	"golive__tip_broadcaster_4": "<b>提示：</b>问问你的观众从何处来，可以有效打开话匣。",
	"golive__tip_broadcaster_5": "<b>提示：</b>感谢观众收看，回复他们的评论，从而保持互动。",
	"golive__tip_broadcaster_6": "<b>提示：</b>如果你在直播时掉线了，换个信号好点的地方。",
	"golive__tip_broadcaster_7": "<b>提示：</b>让别人关注你吧。当你进行下一次直播时，他们会收到通知。",
