	"golive__tip_pre_broadcast_3": "<b>提示：</b>需要点子吗？导览风光，分享才艺，或者聊你感兴趣的话题。",
	"golive__tip_pre_broadcast_4": "<b>提示：</b>直播前要确保你的手机信号较强。",
